#include <torch/extension.h>
#include <c10/hip/HIPStream.h>
#include <hip/hip_runtime.h>
#include <ck/tensor_operation/gpu/element/binary_element_wise_operation.hpp>

__global__ void ck_vecadd_kernel(const float* x, const float* y, float* output, int64_t n) {
    const int64_t index = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (index < n) {
        ck::tensor_operation::element_wise::Add add;
        add(output[index], x[index], y[index]);
    }
}

torch::Tensor run(const torch::Tensor& x, const torch::Tensor& y) {
    TORCH_CHECK(x.is_cuda() && y.is_cuda(), "inputs must be HIP tensors");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32 && y.scalar_type() == torch::kFloat32, "inputs must be float32");
    TORCH_CHECK(x.is_contiguous() && y.is_contiguous() && x.sizes() == y.sizes(), "inputs must be contiguous and shape-compatible");
    auto output = torch::empty_like(x);
    const int threads = 256;
    const int64_t n = x.numel();
    ck_vecadd_kernel<<<(n + threads - 1) / threads, threads, 0, c10::hip::getCurrentHIPStream()>>>(x.data_ptr<float>(), y.data_ptr<float>(), output.data_ptr<float>(), n);
    TORCH_CHECK(hipGetLastError() == hipSuccess, "CK vecadd launch failed");
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, module) {
    module.def("run", &run, "gfx1200 Composable Kernel vector addition");
}
